input.command:
cat > scripts/parse.py <<'E'
import json,re,sys
o=json.load(open('.firecrawl/loadmore.json'))
body=o['body'] if 'body' in o else None
if body is None:
    body=json.loads(o)['body']
items={}
def walk(x):
    if isinstance(x,list):
        if len(x)>15 and isinstance(x[0],str) and re.fullmatch(r'[a-p]{32}',x[0]) and isinstance(x[2],str):
            items[x[0]]=x
            return
        for y in x: walk(y)
for part in body.split('\n=====\n'):
    for m in re.finditer(r'\[\["wrb\.fr","[^"]*","((?:[^"\\]|\\.)*)"',part):
        try: walk(json.loads(json.loads('"'+m.group(1)+'"')))
        except Exception as e: pass
print(len(items),file=sys.stderr)
rows=[]
for k,x in items.items():
    users=x[15] if len(x)>15 else None
    rows.append((k,x[2],x[3],x[4],users,x[8],x[9],x[10],x[18] if len(x)>18 else None))
json.dump(rows,open('.firecrawl/rows.json','w'))
rows.sort(key=lambda r:-(r[4] or 0))
for r in rows[:40]: print(r)
E
python3 -I scripts/parse.py

