import re,json
rows={r[0]:r for r in json.load(open('.firecrawl/merged.json'))}
names="Session Buddy|Toby: Tab|Tab Manager Plus for|Tab Manager by Workona|^Tab Session Manager$|Tab Groups Extension|Tabs Outliner|TooManyTabs|Regex Tab|^Vertical Tabs$|^Tabli|Toby Mini|Tabox|Tab Suspender by Workona|Quick Tabs|Tree Style Tab$|VertiTab|Auto-Group Tabs|TABLERONE|SideTab Pro|Omni -|tabExtend|Save Tab Groups|Toast -|TabXpert".split('|')
out=[]
for l in open('.firecrawl/ids.txt'):
    i=l.split()[0]; r=rows[i]
    if not any(re.search(w,r[1]) for w in names) or r[4]<10000: continue
    L=[x.strip() for x in open(f'.firecrawl/d/{i}.md').read().split('\n') if x.strip()]
    d='?';f='No'
    for k,x in enumerate(L):
        if x=='- Updated' and k+1<len(L) and re.fullmatch(r'[A-Z][a-z]+ \d+, \d{4}',L[k+1]):
